import re

import pytest
from hypothesis import example, given, strategies as st

from ledger.durations.parse import parse_duration

WHOLE_INPUT = re.compile(r"\A(\d{1,6}[smhd])+\Z")


@pytest.mark.invariant("durations_consume_whole_input")
@given(st.from_regex(r"\A(\d{1,6}[smhd])+\Z") | st.text(max_size=12))
@example("100ms")
@example("1.5h")
def test_parse_duration_consumes_whole_input(text):
    if WHOLE_INPUT.match(text):
        assert parse_duration(text) >= 0
    else:
        with pytest.raises(ValueError):
            parse_duration(text)
